import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry (size based on typical CTA button)
  const planeGeom = new PlaneGeometry(4, 1.2);
  const planeMat = new MeshBasicNodeMaterial({ color: 0xffffff });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture asynchronously; material will update when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // Text content
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 42,
      color: (config.intent?.visualSpec?.colors?.paper ||
        '#e8ecf2'),
      align: 'center',
    });
    // Center text on plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // No interactive handlers for this node
  root.userData.handlers = {};

  // Cleanup resources
  root.userData.cleanup = () => {
    // Dispose geometry and material
    planeGeom.dispose();
    planeMat.dispose();
    if (planeMat.map) planeMat.map.dispose();

    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
